import assert from "node:assert/strict";
import { test } from "node:test";

import { quote } from "../../shop/pricing.js";
import { makeShop } from "../helpers.js";

test("bulk discount applies at exactly ten units", () => {
  const { cart } = makeShop();
  cart.add("PEN-01", 10); // 25.00 -> 10% off
  assert.equal(quote(cart.items(), "US").bulkSavings, 250);
});

test("bulk discount not applied at nine units", () => {
  const { cart } = makeShop();
  cart.add("PEN-01", 9);
  assert.equal(quote(cart.items(), "US").bulkSavings, 0);
});

